def main():
 manifests=[ROOT/'model-gate-dependencies.json',ROOT/'model-gate-consumer-dependencies.json'];sources=list({s['runtime_path']:s for p in manifests for s in json.loads(p.read_text())['sources']}.values());assert len(sources)==27
