   b['condition_state']='MODEL_FIXED_TRUE_NONNONE_ROTATION_PATH';b['evidence']+=['descriptor SHA2f4020 optional global_rotation, mapper preserves optional, get_rotation_path'];changed.append((owner,line));note='NonNone selection follows quant-description global rotation path. HF runtime_delta_rotation=False is a different field. Matrix payload and native FP32 math are not validated here.'
